//! Canonical classList and observable PutForwards ordering.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><p id=target class=seed></p><form id=form class=form-class><input name=classList></form><svg id=shape class=shape></svg></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://class-list.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn element_class_list_accessor_descriptor_same_object_prototype_changes_and_native_value(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var subject=document.getElementById('target'),descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'classList');if(!descriptor||!descriptor.enumerable||!descriptor.configurable||descriptor.get.name!=='get classList'||descriptor.set.name!=='set classList'||descriptor.get.length!==0||descriptor.set.length!==1||Object.hasOwn(subject,'classList'))throw 'canonical descriptor';var list=subject.classList;if(list!==subject.classList||list!==descriptor.get.call(subject)||!(list instanceof DOMTokenList))throw 'same object';var calls=0;subject.classList={toString:function(){calls++;return 'A\ud800z';}};if(calls!==1||list.value!=='A\ud800z'||!list.contains('A\ud800z')||subject.getAttribute('class')!==list.value)throw 'native value';var form=document.getElementById('form');if(form.classList!==form.getElementsByTagName('input')[0]||descriptor.get.call(form).value!=='form-class')throw 'named form read';form.classList='field';if(form.classList.value!=='field'||descriptor.get.call(form).value!=='form-class')throw 'named form forwarding';var shape=document.getElementById('shape');if(descriptor.get.call(shape)!==shape.classList||shape.classList.value!=='shape')throw 'SVG receiver';Object.defineProperty(Element.prototype,'classList',{get:function(){return 'author';},configurable:true});if(subject.classList!=='author'||descriptor.get.call(subject)!==list)throw 'override';delete Element.prototype.classList;if(subject.classList!==undefined||descriptor.get.call(subject)!==list)throw 'delete';Object.defineProperty(Element.prototype,'classList',descriptor);if(subject.classList!==list)throw 'restore';
"#);}
#[test]
fn element_class_list_accessor_forwards_original_value_after_author_get_and_ignores_failed_set(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
'use strict';var subject=document.getElementById('target'),descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'classList'),order='',value={toString:function(){order+='convert';return 'bad';}},seen,receiver;var target={set value(v){order+='set';seen=v;receiver=this;}};Object.defineProperty(subject,'classList',{get:function(){order+='get';return target;},configurable:true});if(descriptor.set.call(subject,value)!==undefined||order!=='getset'||seen!==value||receiver!==target||subject.getAttribute('class')!=='seed')throw 'original forwarded value';var symbol=Symbol();descriptor.set.call(subject,symbol);if(seen!==symbol)throw 'symbol passed unchanged';Object.defineProperty(target,'value',{value:'fixed',writable:false,configurable:true});descriptor.set.call(subject,value);if(target.value!=='fixed')throw 'nonwritable';Object.defineProperty(target,'value',{get:function(){return 'readonly';},configurable:true});descriptor.set.call(subject,value);if(target.value!=='readonly')throw 'getter only';var proxy=new Proxy({}, {set:function(t,k,v,r){if(k!=='value'||v!==value||r!==proxy)throw 'trap args';return false;}});target=proxy;descriptor.set.call(subject,value);target=Object.preventExtensions({});descriptor.set.call(subject,value);if(Object.hasOwn(target,'value'))throw 'nonextensible';target=3;try{descriptor.set.call(subject,value);throw 'primitive target';}catch(e){if(!(e instanceof TypeError))throw e;}var marker={};Object.defineProperty(subject,'classList',{get:function(){throw marker;},configurable:true});try{descriptor.set.call(subject,value);throw 'getter abrupt';}catch(e){if(e!==marker)throw e;}target={set value(v){throw marker;}};Object.defineProperty(subject,'classList',{get:function(){return target;},configurable:true});try{descriptor.set.call(subject,value);throw 'setter abrupt';}catch(e){if(e!==marker)throw e;}if(order.indexOf('convert')!==-1)throw 'premature conversion';delete subject.classList;subject.classList='recovered';if(subject.getAttribute('class')!=='recovered')throw 'native recovery';
"#);}
#[test]
fn element_class_list_accessor_brand_precedes_get_and_native_symbol_conversion_is_late(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'classList'),calls=0,invalid={get classList(){calls++;return {};}};try{descriptor.set.call(invalid,{toString:function(){calls++;return 'bad';}});throw 'brand missing';}catch(e){if(!(e instanceof TypeError))throw e;}try{descriptor.get.call(document);throw 'document accepted';}catch(e){if(!(e instanceof TypeError))throw e;}if(calls)throw 'brand before getter';var subject=document.getElementById('target'),list=descriptor.get.call(subject),order='';Object.defineProperty(subject,'classList',{get:function(){order+='get';return list;},configurable:true});descriptor.set.call(subject,{toString:function(){order+='convert';subject.title='effect';return 'A\ud800z';}});if(order!=='getconvert'||list.value!=='A\ud800z'||subject.title!=='effect')throw 'native ordering';try{descriptor.set.call(subject,Symbol());throw 'native symbol';}catch(e){if(!(e instanceof TypeError))throw e;}if(order!=='getconvertget'||list.value!=='A\ud800z')throw 'late Symbol conversion';var owner=document.implementation.createHTMLDocument('inert'),source=owner.createElement('span'),target={};Object.defineProperty(source,'classList',{get:function(){return target;},configurable:true});var value={};descriptor.set.call(source,value);if(target.value!==value||source.getAttribute('class')!==null)throw 'genuine inert author forwarding';
"#);}
#[test]
fn element_class_list_accessor_saved_child_origin_precedes_author_get_and_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var subject=document.getElementById('target'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.Element.prototype,'classList'),list=subject.classList,calls=0;Object.defineProperty(subject,'classList',{get:function(){calls++;return list;},configurable:true});descriptor.set.call(subject,'A\ud800z');if(calls!==1||descriptor.get.call(subject)!==list)throw 'saved child accessor';calls=0;
"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://foreign-class-list.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("descriptor.set.call(subject,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://class-list.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls!==0||list.value!=='A\\ud800z')throw 'origin ordering';descriptor.set.call(subject,'fresh');if(calls!==1||list.value!=='fresh')throw 'fresh recovery';");}
#[test]
fn element_class_list_accessor_forwarded_native_refusal_preserves_attr_observers_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var subject=document.getElementById('target'),list=subject.classList,descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'classList');subject.className='A\ud800z';var a=subject.getAttributeNode('class'),watch=new MutationObserver(function(){});watch.observe(subject,{attributes:true,attributeOldValue:true});var calls=0;Object.defineProperty(subject,'classList',{get:function(){calls++;return list;},configurable:true});"#);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;
for mode in 0..4{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.limits.host.string_bytes=4};let e=p.runtime.execute(r#"descriptor.set.call(subject,'long B\udfffz');"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;}
p.begin_job();run(&mut d,&mut f,&mut p,r#"if(list.value!=='A\ud800z'||a.value!==list.value||watch.takeRecords().length)throw 'refusal publication';var marker={};try{descriptor.set.call(subject,{toString:function(){subject.title='effect';throw marker;}});throw 'abrupt missing';}catch(e){if(e!==marker)throw e;}if(list.value!=='A\ud800z'||subject.title!=='effect'||watch.takeRecords().length!==1)throw 'abrupt retained effects';descriptor.set.call(subject,'fresh B\udfffz');var records=watch.takeRecords();if(records.length!==1||records[0].oldValue!=='A\ud800z'||records[0].attributeName!=='class'||a.value!==list.value||a!==subject.getAttributeNode('class'))throw 'fresh forwarded observation';"#);}
#[test]
fn element_class_list_accessor_unsupported_default_owners_guard_before_token_publication(){let(mut d,mut f,mut p)=fixture();let nodes=p.state.node_limit;p.state.node_limit=d.nodes.len();run(&mut d,&mut f,&mut p,"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/2000/svg','svg');source.className='seed';");let source=p.runtime.execute("source;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();let Value::Host(source)=source else{panic!()};let retained=p.state.retained;let commits=p.state.dom_commits;let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.element_class_list_get(source).unwrap_err();assert!(error.contains("owner storage"),"{error}");assert_eq!((p.state.retained,p.state.dom_commits),(retained,commits));p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"var target={},value={};Object.defineProperty(source,'classList',{get:function(){return target;},configurable:true});Object.getOwnPropertyDescriptor(Element.prototype,'classList').set.call(source,value);if(target.value!==value||source.className!=='seed')throw 'author forwarding recovery';");}
